<script lang="ts">
 import OriginalCardArt from '../cards/OriginalCardArt.svelte';
 import {discoveryMap} from './discovery-movement';
 import {outpostInspection} from './outpost-inspection';
 import type {PublicSetup,PlayerState} from './setup';
 let {game,player,compact=false}:{game:PublicSetup;player:PlayerState;compact?:boolean}=$props();
 let selected=$state('');
 let detail=$state<'power'|'production'|'rules'>('power');
 const places=$derived(discoveryMap(game).locations.filter(p=>p.kind==='system'||p.kind==='shipyard'));
 const preferred=$derived(places.find(p=>game.discovery?.outposts[p.id]?.owner===player.position)?.id??places.find(p=>player.ships.some(s=>s.location===p.id))?.id??places[0].id);
 const location=$derived(places.some(p=>p.id===selected)?selected:preferred);
 const view=$derived(outpostInspection(game,location));
 $effect(()=>{if(!places.some(p=>p.id===selected))selected=preferred;});
</script>

<section class="outpost-ledger" class:compact aria-label="Public outpost control">
 {#if !compact}<p class="scroll-hint">Scroll for production and printed bonus ↓</p>{/if}
 <div class="picker-row">
  <label class="location-picker"><span>Public location</span><select aria-label="Inspect outpost location" value={location} onchange={event=>selected=event.currentTarget.value}>{#each places as place}<option value={place.id}>{place.title}</option>{/each}</select></label>
  {#if compact}<label class="location-picker"><span>Detail</span><select aria-label="Outpost detail" bind:value={detail}><option value="power">Power &amp; control</option><option value="production">Track yields</option><option value="rules">Rule &amp; bonus</option></select></label>{/if}
 </div>
 {#if !compact||detail!=='rules'}
 <header class="location-object">
  <div class="location-art" aria-hidden="true">{#if view.card}<OriginalCardArt id={view.card}/>{:else}<span>⚒</span>{/if}</div>
  <div>{#if !compact}<p class="eyebrow">OUTPOST CONTROL</p><h3>{view.title}</h3>{/if}
   {#if view.owner&&view.outpost}<p class="owner"><span class="disc" class:ore={view.outpost.track==='ore'} aria-hidden="true">{view.outpost.track==='food'?'❧':'✹'}</span><strong>{view.owner.name}</strong> · {view.outpost.placeholder?'placeholder':view.outpost.track==='food'?'Food disc':'Ore disc'}</p>{:else}<p class="owner">No outpost placed</p>{/if}
  </div>
 </header>
 {/if}
 {#if !compact||detail==='power'}
 <div class="power-ledger" aria-label="Summed fleet power">
  {#each view.rows as row,i}<div class="power-row" style={'--faction-tone:'+([170,38,8,275][i])}><strong class="faction-name">{row.name}</strong><div class="ships">{#each row.ships as ship}<span class="level-cube" aria-label={row.name+' level-'+ship.level+' ship'}>{ship.level}</span>{:else}<small>No ships</small>{/each}</div><span class="power-sum"><b>{row.before}</b> power</span></div>{/each}
 </div>
 {/if}
 {#if !compact||detail==='power'||detail==='rules'}
 <div class="control-verdict" aria-live="polite"><p>{compact&&detail==='power'?view.headline:view.explanation}</p>{#if view.pendingResolution}{#if compact&&detail==='power'}<small>Saved control resolution pending.</small>{:else}<strong>Saved control resolution is pending.</strong><small>The current disc stays distinct from the power comparison. Inspection does not apply the transfer.</small>{/if}{/if}</div>
 {/if}
 {#if view.owner&&view.production&&(!compact||detail==='production')}
 <section class="production-record" aria-label={view.owner.name+' current production'}><h4>{view.owner.name} · current track yields</h4><dl><div><dt>Growth if chosen</dt><dd>{view.production.population} Population</dd></div><div><dt>Ore if chosen</dt><dd>{view.production.oreYield} Ore</dd></div></dl><p>{view.outpost?.placeholder?'This placeholder moved no production disc.':'An outpost can return to its track; automation remains permanent.'}</p></section>
 {:else if compact&&detail==='production'}<p class="inspection-note">No outpost is placed here, so this location currently exposes no faction’s production track.</p>{/if}
 {#if (!compact||detail==='rules')&&view.gainBonus}<p class="printed-bonus"><strong>Printed gain-control bonus</strong>{view.gainBonus}</p>{/if}
 {#if !compact||detail==='rules'}<p class="inspection-note">Inspection spends nothing, moves no discs and pays no bonus. Passing through a System does not gain control.</p>{/if}
</section>

